CREATE FUNCTION public.ediel_confirmed_customer_snapshot_v1(p_company_id uuid,p_actor_user_id uuid,p_snapshot_id uuid,p_readset_hash text,p_customer_id uuid,p_site_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE result jsonb;BEGIN IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'customer_source_service_required' USING ERRCODE='42501';END IF;PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();result:=public.ediel_confirmed_customer_snapshot_before_scope_fence_v1(p_company_id,p_actor_user_id,p_snapshot_id,p_readset_hash,p_customer_id,p_site_id);IF EXISTS(SELECT FROM jsonb_array_elements(result->'versions') x WHERE x->>'authorityKind'='bilateral') AND gridex_requested_changes.actor_v1(p_company_id,p_actor_user_id,'read','method_contract') IS NOT TRUE THEN RAISE EXCEPTION 'bilateral_customer_history_reader_forbidden' USING ERRCODE='42501';END IF;RETURN result;END$$;
